    label: str
    rolle: str
    normen: tuple[str, ...]
    entscheidungen: tuple[str, ...]
    stationen: tuple[str, ...]
    pruefraster: tuple[str, ...]
    stop: tuple[str, ...]
    skelette: tuple[str, ...] = field(default_factory=tuple)
    oeffnungssatz: str = ""


