            "BGH, Urteil vom 29.07.1998 - 1 StR 94/98: Ist der einzige Belastungszeuge in Teilen seiner Aussage widerlegt, darf das Gericht dem verbleibenden Aussagekern nur bei gewichtigen, ausserhalb der Aussage liegenden Gruenden folgen und muss diese in den Urteilsgruenden darlegen.",
            "BGH, Urteil vom 26.04.2017 - 2 StR 247/16: Fuer sogenannte legendierte Kontrollen besteht kein allgemeiner Vorrang der StPO vor dem Gefahrenabwehrrecht; die strafprozessuale Verwertbarkeit praeventiv gewonnener Beweise richtet sich nach StPO Paragraf 161 Absatz 2 Satz 1.",
